<?php namespace App\Http\Controllers; use App\Models\{Booking,MeetingRoom}; use Illuminate\Http\Request;
class DashboardController extends Controller { public function __invoke(Request $r){$user=$r->user();$query=Booking::with('room')->latest('start_at'); if(!$user->isAdmin()){$query->where('user_id',$user->id);return view('dashboard', ['bookings'=>$query->take(6)->get(),'stats'=>['upcoming'=>(clone $query)->where('start_at','>',now())->count(),'pending'=>(clone $query)->where('status','pending')->count(),'approved'=>(clone $query)->where('status','approved')->count()]]);} return view('dashboard',['bookings'=>$query->take(8)->get(),'stats'=>['rooms'=>MeetingRoom::where('is_active',true)->count(),'today'=>Booking::whereDate('start_at',today())->count(),'pending'=>Booking::where('status','pending')->count(),'approved'=>Booking::where('status','approved')->count()]]); } }
